function grid$bctkclc(f){
  this.constructor(f);
}
grid$bctkclc.prototype = new DirEvent();
grid$bctkclc.prototype.afterInitFields = function(){
  var p = this._dir;
}
grid$bctkclc.prototype.beforeInit = function(){
  var p = this._dir;
}
grid$bctkclc.prototype.afterInit = function(){
  var p = this._dir, g = p.grid(), dt = g.data;
  if (p.options._data_analysis_struct == '') {
    p.setColumnHidden(0, ['tien', 'tien_nt'], false);
    if (p.options._mau_bc == 1) p.setColumnHidden(0, ['tien', 'tien_nt'], true);
    if (p.options._mau_bc == 2) p.setColumnHidden(0, ['tien_nt'], true);
  }
}
